cd /workspace && python3 - <<'EOF'
import json
d=json.load(open('subject/commands.json'))
pat=['/tmp','/dev/','/home','/etc/','../','http://','https://','curl','wget','nc ','ping','git ','ssh','/proc','/sys','/usr','/bin/','mount','chroot','nsenter','unshare']
for c in d['commands']:
    # only inspect text content of results, which is what subject "saw"
    for blk in c.get('result',{}).get('content',[]):
        t=blk.get('text','')
        for p in pat:
            if p in t:
                print('ordinal',c['ordinal'],'pattern',p,':',t[:200].replace('\n','|'))
EOF
